// Generated by Claude Code
package ui;

import grading.assessment.AssessmentDefinition;
import grading.feedback.Feedback;
import grading.progress.SimilarAnswer;
import grading.progress.StudentProgress;
import grading.scoring.Marks;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.Consumer;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.ScrollPane;
import javafx.scene.layout.VBox;
import javafx.scene.text.Text;
import javafx.scene.text.TextFlow;

/**
 * Everything known about the student selected in the results table: why they need review, the folder and file
 * problems, what was fixed automatically, similar answers, and where each mark was lost, with a button that saves
 * their PDF report.
 */
final class StudentDetailPane {

    private static final double SECTION_SPACING = 6;
    // Feedback marks code with backticks, as in `getTopStudent(...)`; the pane shows it in monospace instead.
    private static final String CODE_MARK = "`";

    private final VBox content = new VBox(SECTION_SPACING);
    private final ScrollPane scroll = new ScrollPane(content);
    private final Button downloadReport = new Button("Download PDF report");
    private StudentProgress shown;

    /**
     * @param downloadReportFor called with the shown student's username when the marker downloads their report
     */
    StudentDetailPane(Consumer<String> downloadReportFor) {
        scroll.setId("studentDetail");
        scroll.setFitToWidth(true);
        scroll.getStyleClass().add("detail-pane");
        content.getStyleClass().add("detail-content");
        downloadReport.setId("downloadReportButton");
        downloadReport.getStyleClass().add("score-sheet-button");
        downloadReport.setOnAction(event -> {
            if (shown != null) {
                downloadReportFor.accept(shown.username());
            }
        });
        show(Optional.empty(), false);
    }

    ScrollPane view() {
        return scroll;
    }

    /** The text shown, for tests. */
    String text() {
        StringBuilder text = new StringBuilder();
        content.getChildren().forEach(node -> {
            if (node instanceof Label label) {
                text.append(label.getText()).append('\n');
            } else if (node instanceof TextFlow flow) {
                flow.getChildren().forEach(run -> text.append(((Text) run).getText()));
                text.append('\n');
            }
        });
        return text.toString();
    }

    /**
     * Shows the student, redrawing only when their data changed.
     *
     * @param student       the selected student, or empty
     * @param reportPresent whether the latest attempt wrote reports that can be opened
     */
    void show(Optional<StudentProgress> student, boolean reportPresent) {
        downloadReport.setDisable(student.isEmpty() || !reportPresent);
        StudentProgress next = student.orElse(null);
        if (next != null && next.equals(shown) && !content.getChildren().isEmpty()) {
            return;
        }
        shown = next;
        content.getChildren().clear();
        if (next == null) {
            content.getChildren().add(muted("Select a student to see their marks and feedback."));
            return;
        }
        Label heading = new Label(next.username() + " — " + next.status().label()
                + (next.scores().isEmpty() ? ""
                        : " — " + Marks.outOf(next.total(), AssessmentDefinition.totalMarks())));
        heading.getStyleClass().add("section-title");
        content.getChildren().add(heading);
        // The same reason as the table's Reason column, so the pane never reads as if nothing is wrong.
        String reason = StudentIssues.reason(next);
        if (!reason.isEmpty()) {
            Label why = line("Why it needs review: " + reason, false);
            why.getStyleClass().add("review-reason");
            content.getChildren().add(why);
        }
        content.getChildren().add(downloadReport);

        section("Folder and file problems", next.issues(), "None.", false);
        section("Fixed automatically", next.corrections(), "Nothing needed fixing.", false);
        section("Similar answers", next.flags().stream().map(SimilarAnswer::describe).toList(), "None.", true);
        showFeedback(next);
    }

    // Every question that lost marks is listed; the explanations are automatic, so the pane says when one is
    // missing instead of implying the list is complete.
    private void showFeedback(StudentProgress next) {
        content.getChildren().add(title("Where marks were lost"));
        if (!next.finished() || next.scores().isEmpty()) {
            content.getChildren().add(muted(next.finished() ? "Not graded." : "Shown once graded."));
            return;
        }
        Map<String, List<Feedback>> byQuestion = new LinkedHashMap<>();
        next.feedback().forEach(feedback ->
                byQuestion.computeIfAbsent(feedback.questionId(), id -> new ArrayList<>()).add(feedback));
        List<AssessmentDefinition.Question> lost = AssessmentDefinition.QUESTIONS.stream()
                .filter(question -> lostMarks(next, question) || byQuestion.containsKey(question.id()))
                .toList();
        if (lost.isEmpty()) {
            content.getChildren().add(muted("No marks lost."));
            return;
        }
        content.getChildren().add(muted("Explanations are generated from the test results and may not cover "
                + "every lost mark. The PDF report lists each test case."));
        for (AssessmentDefinition.Question question : lost) {
            content.getChildren().add(subtitle(question.id() + " — "
                    + Marks.outOf(next.scores().getOrDefault(question.id(), 0.0), question.marks())));
            List<Feedback> items = byQuestion.getOrDefault(question.id(), List.of());
            if (items.isEmpty()) {
                content.getChildren().add(muted("No explanation was found automatically. See the test cases in "
                        + "the PDF report."));
            }
            items.forEach(feedback -> content.getChildren().add(withCode("• " + feedback.text())));
        }
    }

    // A question lost marks when it scored below its maximum, or could not be graded normally.
    private static boolean lostMarks(StudentProgress student, AssessmentDefinition.Question question) {
        double score = student.scores().getOrDefault(question.id(), 0.0);
        return student.problems().containsKey(question.id())
                || question.marks().isPresent() && score < question.marks().getAsDouble();
    }

    private void section(String heading, List<String> items, String empty, boolean flagged) {
        content.getChildren().add(title(heading));
        if (items.isEmpty()) {
            content.getChildren().add(muted(empty));
        } else {
            items.forEach(item -> content.getChildren().add(line("• " + item, flagged)));
        }
    }

    private static Label title(String text) {
        Label label = new Label(text);
        label.getStyleClass().add("detail-title");
        return label;
    }

    private static Label subtitle(String text) {
        Label label = new Label(text);
        label.getStyleClass().add("detail-subtitle");
        return label;
    }

    private static Label muted(String text) {
        Label label = line(text, false);
        label.getStyleClass().add("muted");
        return label;
    }

    // Text between backticks is shown in monospace, without the backticks.
    private static TextFlow withCode(String text) {
        TextFlow flow = new TextFlow();
        String[] parts = text.split(CODE_MARK, -1);
        // An unpaired backtick is not code: show the text as it is.
        if (parts.length % 2 == 0) {
            parts = new String[] {text};
        }
        for (int index = 0; index < parts.length; index++) {
            if (parts[index].isEmpty()) {
                continue;
            }
            Text run = new Text(parts[index]);
            run.getStyleClass().add(index % 2 == 1 ? "feedback-code" : "feedback-text");
            flow.getChildren().add(run);
        }
        return flow;
    }

    private static Label line(String text, boolean flagged) {
        Label label = new Label(text);
        label.setWrapText(true);
        if (flagged) {
            label.getStyleClass().add("flag");
        }
        return label;
    }
}
